/* @lc app=leetcode id=2699 lang=kotlin */
class Solution { fun modifiedGraphEdges(n: Int, edges: Array<IntArray>, source: Int, destination: Int, target: Int): Array<IntArray> = ( { getDist: (Int) -> Long -> getDist(0).let { d1 -> if (d1 < target) emptyArray<IntArray>() else booleanArrayOf(d1 == target.toLong()).let { s -> edges.indices.filter { edges[it][2] == -1 }.map { i -> (if (s[0]) 2000000000 else 1).also { edges[i][2] = it }.run { if (!s[0]) getDist(0).let { d2 -> if (d2 <= target) (target.toLong() - d2).toInt().also { edges[i][2] += it }.also { s[0] = true } else 0L } else 0L } }.run { if (s[0]) edges else emptyArray<IntArray>() } } } } )( { _ -> LongArray(n) { if (it == source) 0L else 100000000000000L }.let { dist -> (1..n).map { edges.map { e -> (if (e[2] != -1 && dist[e[0]] + e[2] < dist[e[1]]) (dist[e[0]] + e[2]).also { dist[e[1]] = it } else null).run { if (e[2] != -1 && dist[e[1]] + e[2] < dist[e[0]]) (dist[e[1]] + e[2]).also { dist[e[0]] = it } } } }.run { dist[destination] } } ) }